<?php
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='send'&&isset($_POST['availability_start'])){
 try{
  if(!verifyCsrf($_POST['csrf']??''))throw new RuntimeException('Invalid request.');if(!$deliveryReady)throw new RuntimeException('Configure email delivery before sending.');$window=validateInterviewWindow($_POST);$slots=buildInterviewSlots($window);$ids=array_values(array_unique(array_filter(array_map('strval',$_POST['candidate_ids']??[]))));$subject=trim((string)($_POST['subject']??''));$body=trim((string)($_POST['body']??''));if(!$ids||$subject===''||$body==='')throw new RuntimeException('Select recipients and complete the availability window.');
  $marks=implode(',',array_fill(0,count($ids),'?'));$recipientStmt=$pdo->prepare("SELECT c.id,c.name,c.email FROM candidates c WHERE c.job_id=? AND c.id IN ($marks) AND c.email IS NOT NULL AND c.email<>'' AND NOT EXISTS(SELECT 1 FROM interview_invite_locks il WHERE il.profile_id=? AND il.candidate_id=c.id AND il.active=1)");$recipientStmt->execute(array_merge([$jobId],$ids,[$profile['id']]));$recipients=$recipientStmt->fetchAll();if(count($recipients)!==count($ids))throw new RuntimeException('A selected candidate is invalid, missing email, or already invited.');
