  foreach($recipients as $recipient){$invitation=$invitations[$recipient['id']];try{$deliverInterview($recipient['email'],$subject,$invitation['html']);$updateRecipient->execute(['sent',date('Y-m-d H:i:s'),null,$batchId,$recipient['id']]);$pdo->prepare("UPDATE interview_invitations SET status='awaiting_confirmation',sent_at=NOW() WHERE id=?")->execute([$invitation['id']]);$move->execute([$recipient['id'],$jobId]);$lock->execute([$profile['id'],$recipient['id'],$batchId]);$audit->execute([$user['id'],'interview.invitation_sent','candidate',$recipient['id'],json_encode(['batch_id'=>$batchId,'schedule_batch_id'=>$scheduleBatchId,'job_id'=>$jobId,'availability'=>$windowLabel,'timezone'=>$window['timezone'],'transport'=>$deliveryName,'booking_host'=>'nonceblox.com','outcome'=>'success'])]);$sent++;}catch(Throwable $mailError){$updateRecipient->execute(['failed',null,'Delivery failed.',$batchId,$recipient['id']]);$pdo->prepare("UPDATE interview_invitations SET status='failed' WHERE id=?")->execute([$invitation['id']]);$failed++;}}
  $status=$failed===0?'sent':($sent?'partial':'failed');$pdo->prepare('UPDATE email_batches SET status=? WHERE id=?')->execute([$status,$batchId]);$audit->execute([$user['id'],'interview.batch_completed','email_batch',(string)$batchId,json_encode(['schedule_batch_id'=>$scheduleBatchId,'job_id'=>$jobId,'sent'=>$sent,'failed'=>$failed,'outcome'=>$status])]);header('Location: interview_invite.php?job_id='.$jobId.'&scheduled='.$sent.'&failed='.$failed);exit;
